</div>
<script>
const DEG = Math.PI / 180;
const root = document.documentElement;
function css(v) { return getComputedStyle(root).getPropertyValue(v).trim(); }

// math model
function project(x, y, z, az, el) {
  const ca = Math.cos(az * DEG), sa = Math.sin(az * DEG);
  const ce = Math.cos(el * DEG), se = Math.sin(el * DEG);
  const x1 = x * ca + z * sa;
  const y1 = y;
  const z1 = -x * sa + z * ca;
  const x2 = x1;
  const y2 = y1 * ce - z1 * se;
  return { sx: x2, sy: -y2 };
}

function gdPoint(t) {
  const x = Math.pow(0.8, t);
  const y = Math.pow(1.2, t);
  return { x, y, f: x*x - y*y };
}

// verification
(function() {
  const p5 = gdPoint(5);
  console.assert(Math.abs(p5.x - 0.328) < 0.001, 'x');
  console.assert(Math.abs(p5.y - 2.488) < 0.001, 'y');
  console.assert(Math.abs(p5.f + 6.082) < 0.1, 'f');
  const t = project(1,1,0,45,30);
  console.assert(!isNaN(t.sx) && !isNaN(t.sy), 'project');
})();

// state
let azimuth = 45, elevation = 30, step = 5;
const canvas = document.getElementById('stage');
const ctx = canvas.getContext('2d');
let W, H;

function setupCanvas() {
  const wrap = document.getElementById('stageWrap');
  const rect = wrap.getBoundingClientRect();
  const w = rect.width, h = rect.height;
  const aspect = 16/9;
  let cw, ch;
  if (w / h > aspect) { ch = h; cw = h * aspect; }
  else { cw = w; ch = w / aspect; }
  W = canvas.width = Math.round(cw);
  H = canvas.height = Math.round(ch);
  canvas.style.width = W + 'px';
  canvas.style.height = H + 'px';
}

function draw() {
  const accent = css('--accent');
  const line = css('--line');
  const ink = css('--ink');
  const text2 = css('--text2');
  const dark = root.getAttribute('data-theme') === 'dark';

  // compute complementary color for y-direction curve
  const acR = parseInt(accent.slice(1,3),16) || 0;
  const acG = parseInt(accent.slice(3,5),16) || 0;
  const acB = parseInt(accent.slice(5,7),16) || 0;
  const comp = '#' + (255-acR).toString(16).padStart(2,'0')
             + (255-acG).toString(16).padStart(2,'0')
             + (255-acB).toString(16).padStart(2,'0');

  const gridX = [], gridY = [];
  for (let x = -3; x <= 3; x += 0.3) gridX.push(x);
  gridY = gridX.slice();

  const gridPts = [];
  for (let x of gridX) {
    for (let y of gridY) {
      const z = x*x - y*y;
      const p = project(x, y, z, azimuth, elevation);
      gridPts.push({x,y,z,sx:p.sx,sy:p.sy});
    }
  }

  const xCurve = [];
  for (let x = -3; x <= 3; x += 0.05) {
    const z = x*x;
    const p = project(x, 0, z, azimuth, elevation);
    xCurve.push(p);
  }

  const yCurve = [];
  for (let y = -3; y <= 3; y += 0.05) {
    const z = -y*y;
    const p = project(0, y, z, azimuth, elevation);
    yCurve.push(p);
  }

  const traj = [];
  for (let t = 0; t <= step; t++) {
    const g = gdPoint(t);
    const p = project(g.x, g.y, g.f, azimuth, elevation);
    traj.push(p);
  }

  const allPts = gridPts.map(p=>({sx:p.sx,sy:p.sy})).concat(xCurve).concat(yCurve).concat(traj);
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (let p of allPts) {
    if (p.sx < minX) minX = p.sx;
    if (p.sx > maxX) maxX = p.sx;
    if (p.sy < minY) minY = p.sy;
    if (p.sy > maxY) maxY = p.sy;
  }
  const rangeX = maxX - minX || 1;
  const rangeY = maxY - minY || 1;
  const scale = Math.min(W / rangeX, H / rangeY) * 0.85;
  const offX = (W - (minX + maxX) * scale) / 2;
  const offY = (H - (minY + maxY) * scale) / 2;

  function toScreen(p) {
    return { x: p.sx * scale + offX, y: p.sy * scale + offY };
  }

  ctx.clearRect(0, 0, W, H);

  // grid
  ctx.strokeStyle = line;
  ctx.lineWidth = 0.5;
  for (let i = 0; i < gridX.length; i++) {
    ctx.beginPath();
    for (let j = 0; j < gridY.length; j++) {
      const idx = i * gridY.length + j;
      const s = toScreen(gridPts[idx]);
      if (j === 0) ctx.moveTo(s.x, s.y);
      else ctx.lineTo(s.x, s.y);
    }
    ctx.stroke();
  }
  for (let j = 0; j < gridY.length; j++) {
    ctx.beginPath();
    for (let i = 0; i < gridX.length; i++) {
      const idx = i * gridY.length + j;
      const s = toScreen(gridPts[idx]);
      if (i === 0) ctx.moveTo(s.x, s.y);
      else ctx.lineTo(s.x, s.y);
    }
    ctx.stroke();
  }

  // x-direction highlight
  ctx.strokeStyle = accent;
  ctx.lineWidth = 2.5;
  ctx.setLineDash([]);
  ctx.beginPath();
  for (let i = 0; i < xCurve.length; i++) {
    const s = toScreen(xCurve[i]);
    if (i === 0) ctx.moveTo(s.x, s.y);
    else ctx.lineTo(s.x, s.y);
  }
  ctx.stroke();

  // y-direction highlight
  ctx.strokeStyle = comp;
  ctx.lineWidth = 2.5;
  ctx.setLineDash([6, 4]);
  ctx.beginPath();
  for (let i = 0; i < yCurve.length; i++) {
    const s = toScreen(yCurve[i]);
    if (i === 0) ctx.moveTo(s.x, s.y);
    else ctx.lineTo(s.x, s.y);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  // trajectory line
  for (let t = 0; t < traj.length - 1; t++) {
    const alpha = 0.15 + 0.85 * (t / (traj.length - 1));
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1.5;
    const s0 = toScreen(traj[t]);
    const s1 = toScreen(traj[t+1]);
    ctx.beginPath();
    ctx.moveTo(s0.x, s0.y);
    ctx.lineTo(s1.x, s1.y);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // current point
  const last = toScreen(traj[traj.length-1]);
  if (dark) {
    ctx.shadowColor = accent;
    ctx.shadowBlur = 16;
  }
  ctx.fillStyle = accent;
  ctx.beginPath();
  ctx.arc(last.x, last.y, 6, 0, 2*Math.PI);
  ctx.fill();
  ctx.shadowBlur = 0;
  if (!dark) {
    ctx.strokeStyle = accent;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(last.x, last.y, 9, 0, 2*Math.PI);
    ctx.stroke();
  }

  // legend
  const lx = 12, ly = 18;
  ctx.font = '12px ' + css('--sans');
  ctx.textBaseline = 'top';
  ctx.fillStyle = accent;
  ctx.fillRect(lx, ly, 14, 4);
  ctx.fillStyle = ink;
  ctx.fillText('沿x方向', lx + 20, ly - 4);
  ctx.fillStyle = comp;
  ctx.fillRect(lx, ly + 20, 14, 4);
  ctx.fillStyle = ink;
  ctx.fillText('沿y方向', lx + 20, ly + 16);
}

function updateReadout() {
  const g = gdPoint(step);
  document.getElementById('readStep').textContent = step;
  document.getElementById('readCoord').textContent = '(' + g.x.toFixed(3) + ', ' + g.y.toFixed(3) + ')';
  document.getElementById('readF').textContent = g.f.toFixed(3);
  document.getElementById('stepVal').textContent = step;
}

function animateValue(el, start, end, duration, decimals) {
  const startTime = performance.now();
  function tick(now) {
    const t = Math.min((now - startTime) / duration, 1);
    const v = end - (end - start) * Math.pow(1 - t, 3);
    if (decimals !== undefined) {
      el.textContent = v.toFixed(decimals);
    } else {
      el.textContent = Math.round(v);
    }
    if (t < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

function update() {
  draw();
}

// interactions
let dragging = false, startX, startY, startAz, startEl;
canvas.addEventListener('mousedown', (e) => {
  dragging = true;
  startX = e.clientX; startY = e.clientY;
  startAz = azimuth; startEl = elevation;
  canvas.style.cursor = 'grabbing';
});
window.addEventListener('mousemove', (e) => {
  if (!dragging) return;
  const dx = e.clientX - startX;
  const dy = e.clientY - startY;
  azimuth = startAz + dx * 0.5;
  elevation = Math.min(90, Math.max(0, startEl + dy * 0.5));
  update();
});
window.addEventListener('mouseup', () => {
  if (dragging) {
    dragging = false;
    canvas.style.cursor = 'grab';
  }
});
canvas.style.cursor = 'grab';

document.getElementById('step').addEventListener('input', (e) => {
  const oldStep = step;
  const newStep = parseInt(e.target.value);
  step = newStep;

  // animate readout values
  const oldG = gdPoint(oldStep);
  const newG = gdPoint(newStep);
  const stepEl = document.getElementById('readStep');
  const coordEl = document.getElementById('readCoord');
  const fEl = document.getElementById('readF');
  const valEl = document.getElementById('stepVal');

  animateValue(stepEl, oldStep, newStep, 300);
  animateValue(valEl, oldStep, newStep, 300);
  animateValue(coordEl, oldG.x, newG.x, 300, 3);
  // for y and f we need separate animations but we can update them directly with flash
  // simpler: just set them with a small delay
  setTimeout(() => {
    document.getElementById('readCoord').textContent = '(' + newG.x.toFixed(3) + ', ' + newG.y.toFixed(3) + ')';
    document.getElementById('readF').textContent = newG.f.toFixed(3);
  }, 300);

  update();
});

// init
setupCanvas();
updateReadout();
update();

// handle theme change
new MutationObserver(update).observe(root, {attributes:true, attributeFilter:['data-theme']});
</script>", "spec": {"core_insight": "鞍点处沿一个方向向上弯曲（正曲率），沿正交方向向下弯曲（负曲率），梯度下降会先被吸引到鞍点附近然后沿负曲率方向逃离。", "render_medium": "canvas", "render_medium_reason": "3D曲面需要实时旋转和网格绘制，canvas提供逐帧重绘能力，适合动态视角和轨迹动画。", "aesthetic_direction": "lab-dark", "direction_reason": "暗色背景突出曲面高亮曲线和发光轨迹，符合算法模拟的仪器感。", "palette": ["#1a1a2e", "#e0e0e0", "#ff6b6b", "#4ecdc4"], "signature_detail": "发光小球沿梯度下降路径移动，带有淡出轨迹线", "layout_pattern": "stage+readout-row", "layout_skeleton": "controls wrap row (100%) / stage canvas 16:9 (100%) / readout row (3x 1fr)", "state_model": [{"name": "azimuth", "type": "float", "range_or_values": "0..360", "initial": 45}, {"name": "elevation", "type": "float", "range_or_values": "0..90", "initial": 30}, {"name": "step", "type": "int", "range_or_values": "0..50", "initial": 5}], "interactions": [{"trigger": "canvas#stage mousedown+mousemove", "effect": "更新azimuth和elevation，重绘曲面、曲线和轨迹"}, {"trigger": "input#step-slider input", "effect": "更新step，重绘轨迹（显示到当前步）"}], "render_contract": "update()从当前状态(azimuth, elevation, step)重新计算3D投影，绘制曲面网格、沿x和y方向的高亮曲线、梯度下降轨迹（起点(1,1)，学习率0.1），并更新readout行显示当前步的坐标和函数值。", "update": "update()从当前状态(azimuth, elevation, step)重新计算3D投影，绘制曲面网格、沿x和y方向的高亮曲线、梯度下降轨迹（起点(1,1)，学习率0.1），并更新readout行显示当前步的坐标和函数值。", "initial_paint": "曲面f(x,y)=x²-y²以灰色网格线显示在[-3,3]×[-3,3]区域，沿x轴方向（y=0）的曲线以红色高亮，沿y轴方向（x=0）的曲线以蓝色高亮。梯度下降轨迹从点(1,1)开始，学习率0.1，已进行5步，轨迹点以发光小球和淡出线显示，当前点坐标(0.328, 2.488, -6.082)。视角方位角45°，仰角30°，同时显示两个方向。底部readout行显示当前步数、坐标和f值。", "visible_encodings": [{"quantity": "曲面高度 f(x,y)", "mark": "网格曲面", "where": "整个舞台"}, {"quantity": "沿x方向曲率（向上弯曲）", "mark": "红色高亮曲线（y=0）", "where": "曲面上沿x轴"}, {"quantity": "沿y方向曲率（向下弯曲）", "mark": "蓝色高亮曲线（x=0）", "where": "曲面上沿y轴"}, {"quantity": "梯度下降轨迹", "mark": "发光小球+路径线", "where": "从起点(1,1)到当前步"}, {"quantity": "当前点坐标和f值", "mark": "文本读数", "where": "底部readout行"}], "comparison_states": ["沿x方向高亮曲线（红色）", "沿y方向高亮曲线（蓝色）"], "math_model": {"formula": "f(x,y)=x²-y²", "screen_mapping": "使用正交投影，数学坐标(x,y,f(x,y))先绕y轴旋转azimuth，再绕x轴旋转elevation，投影到屏幕（忽略z深度），屏幕x向右，y向上（渲染时翻转y）", "invariants": ["沿x方向曲线: y=0, z=x²", "沿y方向曲线: x=0, z=-y²", "梯度下降更新: x_{t+1}=x_t - 2α x_t, y_{t+1}=y_t + 2α y_t, 其中α=0.1"]}, "verification_cases": [{"input": {"azimuth": 45, "elevation": 30, "step": 5}, "expected": "曲面显示，红色曲线沿x轴，蓝色曲线沿y轴，轨迹从(1,1)开始，5步后x=1*0.8^5≈0.328, y=1*1.2^5≈2.488, f≈0.1076-6.190≈-6.082"}, {"input": {"azimuth": 0, "elevation": 90}, "expected": "俯视图，曲面等高线投影，x方向曲线和y方向曲线交叉于原点"}]}, "id": "b1"}, {"type": "formula", "latex": "f(x,y)=x^{2}-y^{2},\quad \nabla f=(2x,\,-2y),\quad \mathbf{H}=\operatorname{diag}(2,\,-2)", "caption": "函数、梯度与 Hessian 矩阵", "id": "b2"}, {"type": "callout", "label": "曲率特征", "text": "沿 $x$ 方向曲率为正（向上弯曲），沿 $y$ 方向曲率为负（向下弯曲），Hessian 特征值一正一负。", "id": "b3"}, {"type": "quiz", "kind": "objective", "stem": "对于函数 $f(x,y)=x^2-y^2$，点 $(0,0)$ 是：", "choices": [{"key": "a", "text": "局部极小值点"}, {"key": "b", "text": "局部极大值点"}, {"key": "c", "text": "鞍点"}, {"key": "d", "text": "不是临界点"}], "answer": "c", "explain": "点 $(0,0)$ 处梯度 $\nabla f = (2x, -2y)$ 为零，是临界点。Hessian 矩阵 $\begin{bmatrix}2 & 0\\0 & -2\end{bmatrix}$ 的特征值为 $2$ 和 $-2$，一正一负，因此该点是鞍点。沿 $x$ 方向曲率为正（向上弯曲），沿 $y$ 方向曲率为负（向下弯曲），不是局部极值。", "id": "b4"}], "layout": {"kind": "compose", "areas": [{"blockIds": ["b1"], "col": [1, 9]}, {"blockIds": ["b2"], "col": [9, 13]}, {"blockIds": ["b3"], "col": [1, 5]}, {"blockIds": ["b4"], "col": [5, 11]}]}}。本 block 教学意图: 显示函数 f(x,y)=x²-y²、梯度 ∇f=(2x, -2y)、Hessian 矩阵 diag(2, -2)
